There's clear duplication between l148 and l151; one focuses on Joins, the other on Leaves but they're identical.
Try to provide a more declarative approach, like this one (for example):

```csharp
/// <summary>
/// The joins and leaves of a presence diff that a handler should hear about.
/// A key that replaces its metas (a new join and a leave of the previous <c>phx_ref</c>
/// in the same diff) and is still present has neither joined nor left.
/// </summary>
internal sealed record PresenceChanges(IReadOnlySet<string> Joined, IReadOnlySet<string> Left)
{
    public bool HasJoins => Joined.Count > 0;
    public bool HasLeaves => Left.Count > 0;

    public static PresenceChanges From<TPresence>(
        PresenceDiffPayload<TPresence> diff,
        IReadOnlyDictionary<string, List<TPresence>> currentState)
        where TPresence : BasePresence
    {
        var replaced = diff.Joins!.Keys
            .Intersect(diff.Leaves!.Keys)
            .Where(currentState.ContainsKey)
            .ToHashSet();

        return new PresenceChanges(
            Joined: diff.Joins.Keys.Except(replaced).ToHashSet(),
            Left: diff.Leaves.Keys.Except(replaced).ToHashSet());
    }
}
```

