var changes = PresenceChanges.From(obj.Payload, this.CurrentState);
if (changes.HasJoins) this.NotifyPresenceEventHandlers(IRealtimePresence.EventType.Join);
if (changes.HasLeaves) this.NotifyPresenceEventHandlers(IRealtimePresence.EventType.Leave);
